修法:
改成按文件内容哈希，只有真正改过的文件才换 URL：
```js
const { createHash } = require('crypto');
const { readFileSync, existsSync } = require('fs');
const { join } = require('path');
const cache = new Map();

hexo.extend.helper.register('asset_version', function (relPath) {
  if (!relPath) return '';                      // 调用方必须传路径
  if (cache.has(relPath)) return cache.get(relPath);
  // 先找主题 source，再找站点 source（style.css 由 styl 编译，回退到 styl 源文件哈希）
  const candidates = [
    join(hexo.theme_dir, 'source', relPath),
    join(hexo.source_dir, relPath),
    join(hexo.theme_dir, 'source', relPath.replace(/^css\/style\.css$/, 'css/style.styl'))
  ];
  let v = 'na';
  for (const p of candidates) {
    if (existsSync(p)) {
      v = createHash('sha1').update(readFileSync(p)).digest('hex').slice(0, 8);
      break;
    }
  }
  cache.set(relPath, v);
  return v;
});
```
模板改为 `?v=<%= asset_version('js/pjax.js') %>` 逐文件调用。style.css 的哈希基于 style.styl 会漏掉被 @import 的 _partial/*.styl 变更，稳妥做法是改用注册 `after_generate` 过滤器读取 `public/css/style.css` 的哈希，或者干脆把 jquery/script.js 这类不变文件的 `?v=` 去掉（它们有 ETag 就够了），只给自研的 4 个文件加哈希。

改成构建期生成歌单，把「文件存在」变成构建约束：新增 `themes/cosmic/scripts/music-playlist.js`：
```js
const { readdirSync, existsSync } = require('fs');
const { join } = require('path');
hexo.extend.helper.register('music_playlist', function () {
  const dir = join(hexo.source_dir, 'music');
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter(f => /\.mp3$/i.test(f)).sort().map(f => {
    const base = f.replace(/\.mp3$/i, '');
    const m = base.match(/^(.*?)\s+-\s+(.*)$/);   // 「歌名 - 歌手」
    return {
      name: m ? m[1].trim() : base,
      artist: m ? m[2].trim() : '',
      url: hexo.config.root + 'music/' + encodeURIComponent(f)   // 逐段编码，彻底免疫 # % ? +
    };
  });
});
```
在 after-footer.ejs 里注入 `<script>window.__PLAYLIST__ = <%- JSON.stringify(music_playlist()) %>;</script>`，music-player.js 改成读 `window.__PLAYLIST__ || []`。这样加歌/删歌/改名只需动文件，代码零改动，也不可能再出现引用不存在文件的情况。

